1	//! UTF-8 helpers — 1:1 port of `sqlite-source/src/utf.c` core functions.
2	//!
3	//! Implements the building blocks used throughout SQLite for UTF-8
4	//! encoding/decoding: `utf8_read`, `utf8_write`, `utf8_char_count`.
5	//! The decoder corresponds to `sqlite3Utf8Read` (utf.c:175-194) and the
6	//! encoder to `sqlite3AppendOneUtf8Character` (utf.c:114-135).
7	//!
8	//! # Behavior contract
9	//!
10	//! - 1-4 byte UTF-8 sequences decode as the corresponding codepoint
11	//! - `0x80..=0xBF` as a first byte is treated as a single literal byte
12	//!   (per `utf.c:155-158`); the over-long form of any codepoint ≥ 0x80
13	//!   is *accepted* (`utf.c:160-162`), not replaced with U+FFFD
14	//! - Surrogate values (0xD800..=0xDFFF) and noncharacters (0xFFFE/0xFFFF)
15	//!   are normalized to U+FFFD on read
16	//! - 5+ byte leading bytes (0xF8+) and overlong NUL/7-bit forms are
17	//!   all folded to U+FFFD (the C decoder reaches this outcome via
18	//!   `sqlite3Utf8Trans1` and the post-decode validity check)
19	//! - All input ranges are handled without panicking; the result type
20	//!   for the decoder is `(u32, usize)` because U+FFFD is a valid `char`
21	//!   but the caller may want the raw 32-bit value for diagnostic paths
22	
23	/// `sqlite3Utf8Trans1` lookup table (utf.c:52-61).
24	///
25	/// Index `i` corresponds to a leading byte of `0xC0 + i` and stores the
26	/// initial value of the codepoint accumulator *before* the continuation
27	/// bytes are folded in. Two-byte leading bytes map to 0x02..=0x1F,
28	/// three-byte to 0x00..=0x0F, and four-byte to 0x00..=0x07. Indices
29	/// for 5+-byte leading bytes (0xF8+) are 0x00..=0x05, which combined
30	/// with the validity check below guarantees such sequences end up as
31	/// either a sub-0x80 value or a valid (non-surrogate, non-FFFE) number.
32	const UTF8_TRANS1: [u8; 64] = [
33	    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, // 0xC0 - 0xC7
34	    0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f, // 0xC8 - 0xCF
35	    0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, // 0xD0 - 0xD7
36	    0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f, // 0xD8 - 0xDF
37	    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, // 0xE0 - 0xE7
38	    0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f, // 0xE8 - 0xEF
39	    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, // 0xF0 - 0xF7
40	    0x00, 0x01, 0x02, 0x03, 0x00, 0x01, 0x00, 0x00, // 0xF8 - 0xFF
41	];
42	
43	// ============================================================================
44	// utf8_read — corresponds to sqlite3Utf8Read (utf.c:175-194)
45	// ============================================================================
46	
47	/// Read a single UTF-8 character from the start of `bytes`.
48	///
49	/// Returns `(codepoint, byte_len)`. `byte_len` is the number of bytes
50	/// consumed from `bytes` (1-4) — for empty input the result is `(0, 0)`.
51	/// On any malformed input the codepoint is U+FFFD; the byte length is
52	/// still 1 (the leading byte is consumed) for all non-empty inputs,
53	/// matching `sqlite3Utf8Read`.
54	///
55	/// # Example
56	///
57	/// ```
58	/// use libsqlite_rs::util::utf8::utf8_read;
59	/// assert_eq!(utf8_read(b"A"),     (0x41, 1));
60	/// assert_eq!(utf8_read("\u{4e2d}".as_bytes()), (0x4e2d, 3)); // 中
61	/// assert_eq!(utf8_read("\u{1f600}".as_bytes()), (0x1F600, 4)); // 😀
62	/// ```
63	pub fn utf8_read(bytes: &[u8]) -> (u32, usize) {
64	    if bytes.is_empty() {
65	        return (0, 0);
66	    }
67	    let first = bytes[0];
68	    if first < 0xc0 {
69	        // ASCII fast path. Also handles continuation bytes used as
70	        // leaders (0x80..=0xBF) per utf.c:155-158: returned as-is.
71	        return (first as u32, 1);
72	    }
73	    // Multi-byte: initial accumulator from the trans1 table, then
74	    // greedy fold of continuation bytes (0x80..=0xBF).
75	    let mut codepoint = UTF8_TRANS1[(first - 0xc0) as usize] as u32;
76	    let mut len = 1usize;
77	    while len < bytes.len() && (bytes[len] & 0xc0) == 0x80 {
78	        // SAFE-equivalent: index is bounded by bytes.len() (loop guard).
79	        codepoint = (codepoint << 6) + (0x3f & bytes[len] as u32);
80	        len += 1;
81	    }
82	    // utf.c:189-191: post-decode validity check.
83	    if codepoint < 0x80
84	        || (codepoint & 0xFFFF_F800) == 0xD800
85	        || (codepoint & 0xFFFF_FFFE) == 0xFFFE
86	    {
87	        codepoint = 0xFFFD;
88	    }
89	    (codepoint, len)
90	}
91	
92	// ============================================================================
93	// utf8_write — corresponds to sqlite3AppendOneUtf8Character (utf.c:114-135)
94	// ============================================================================
95	
96	/// Write a single UTF-8 character with codepoint `c` into `buf`.
97	///
98	/// `n` is the caller's stated buffer capacity; the write is clamped to
99	/// `min(n, buf.len())` to prevent buffer overruns. The return value is
100	/// the number of bytes actually written — `0` if `n` is smaller than
101	/// the encoding size of `c`, otherwise `1`, `2`, `3`, or `4` depending
102	/// on the codepoint, matching `sqlite3AppendOneUtf8Character`.
103	///
104	/// Codepoint ranges (mirroring C):
105	/// - `c < 0x0080`  → 1 byte
106	/// - `c < 0x0800`  → 2 bytes
107	/// - `c < 0x10000` → 3 bytes
108	/// - `c >= 0x10000`→ 4 bytes
109	///
110	/// The encoder does not validate `c` (it is just a bit-pattern source).
111	/// Callers that have decoded via `utf8_read` can rely on `c` being
112	/// either a valid codepoint or U+FFFD.
113	pub fn utf8_write(buf: &mut [u8], c: u32, n: usize) -> usize {
114	    let cap = n.min(buf.len());
115	    if c < 0x0080 && cap >= 1 {
116	        buf[0] = c as u8;
117	        return 1;
118	    }
119	    if c < 0x0800 && cap >= 2 {
120	        buf[0] = 0xC0 | ((c >> 6) as u8 & 0x1F);
121	        buf[1] = 0x80 | (c as u8 & 0x3F);
122	        return 2;
123	    }
124	    if c < 0x10000 && cap >= 3 {
125	        buf[0] = 0xE0 | ((c >> 12) as u8 & 0x0F);
126	        buf[1] = 0x80 | ((c >> 6) as u8 & 0x3F);
127	        buf[2] = 0x80 | (c as u8 & 0x3F);
128	        return 3;
129	    }
130	    if cap >= 4 {
131	        buf[0] = 0xF0 | ((c >> 18) as u8 & 0x07);
132	        buf[1] = 0x80 | ((c >> 12) as u8 & 0x3F);
133	        buf[2] = 0x80 | ((c >> 6) as u8 & 0x3F);
134	        buf[3] = 0x80 | (c as u8 & 0x3F);
135	        return 4;
136	    }
137	    0
138	}
139	
140	// ============================================================================
141	// utf8_char_count — corresponds to sqlite3Utf8CharLen (utf.c:475-490)
142	// ============================================================================
143	
144	/// Count UTF-8 characters in `s`, stopping at the first 0x00 byte or
145	/// the end of the slice, whichever comes first.
146	///
147	/// This mirrors `sqlite3Utf8CharLen(zIn, -1)`. The `-1` nByte in C means
148	/// "scan until NUL"; the Rust equivalent stops at `s.len()` because Rust
149	/// slices do not have a guaranteed NUL terminator — the slice boundary
150	/// is also a valid stop condition.
151	pub fn utf8_char_count(s: &[u8]) -> usize {
152	    let mut count: usize = 0;
153	    let mut i: usize = 0;
154	    while i < s.len() && s[i] != 0 {
155	        // SQLITE_SKIP_UTF8(z) — utf.c forward-declared in sqliteInt.h.
156	        // For first < 0x80, one byte; otherwise consume leading + all
157	        // continuation bytes.
158	        let first = s[i];
159	        if first < 0x80 {
160	            i += 1;
161	        } else {
162	            i += 1;
163	            while i < s.len() && (s[i] & 0xc0) == 0x80 {
164	                i += 1;
165	            }
166	        }
167	        count += 1;
168	    }
169	    count
170	}
171	
172	// ============================================================================
173	// 单元测试(快速冒烟,完整测试在 tests/util/utf8.rs)
174	// ============================================================================
175	
176	#[cfg(test)]
177	mod tests {
178	    use super::*;
179	
180	    #[test]
181	    fn read_ascii() {
182	        assert_eq!(utf8_read(b"a"), (0x61, 1));
183	        assert_eq!(utf8_read(b"\0"), (0, 1)); // NUL treated as ASCII
184	    }
185	
186	    #[test]
187	    fn read_two_byte() {
188	        // U+00A0 = 0xC2 0xA0
