204	    #[test]
205	    fn read_surrogate_replaced_with_fffd() {
206	        // U+D800 in canonical 3-byte form = 0xED 0xA0 0x80
207	        assert_eq!(utf8_read(&[0xED, 0xA0, 0x80]), (0xFFFD, 3));
208	        // U+DFFF = 0xED 0xBF 0xBF
209	        assert_eq!(utf8_read(&[0xED, 0xBF, 0xBF]), (0xFFFD, 3));
