543	    fn strlike_escape_zero_disables_escape() {
544	        // esc=0 时,任何字符都是字面量
545	        assert_eq!(sl("a%b", "axb", 0), SQLITE_MATCH);
546	        assert_eq!(sl("a%b", "a%b", 0), SQLITE_MATCH);
